import json

# Pattern matching input: top-right 3s become full vertical bar on right
# Bottom-center 3s become full vertical bar on left 
# 2s coalesce into rectangle

grid = [
    [8]*19 for _ in range(10)
]

# Left 3-bar: cols 4-8 (from bottom 3s at 5-8)
for c in range(4, 9):
    for r in range(10):
        grid[r][c] = 3

# Right 3-bar: cols 14-18 (from top 3s at 15-18)
for c in range(14, 19):
    for r in range(10):
        grid[r][c] = 3

# 2s rectangle where input 2s were: rows 2-5, cols 5-8
# But those cols are IN the left 3-bar!
# So shift 2s to right side: cols 9-12
for r in range(2, 6):
    for c in range(9, 13):
        grid[r][c] = 2

print("Two 3-bars with 2s between them:")
for i, row in enumerate(grid):
    print(''.join('##' if x==3 else 'OO' if x==2 else 'XX' for x in row))

submit = grid
result = {"action": "submit", "grid": submit}
print("\n" + json.dumps(result))

